  `role_code` TEXT,
  `role_description` TEXT,
  PRIMARY KEY (`role_code`)
);

CREATE TABLE `Users` (
  `user_id` NUMBER,
  `role_code` TEXT REFERENCES `Roles`(`role_code`),
  `user_name` TEXT,
  `user_login` TEXT,
  `password` TEXT,
  PRIMARY KEY (`user_id`)
);

CREATE TABLE `Document_Structures` (
  `document_structure_code` TEXT,
  `parent_document_structure_code` TEXT,
  `document_structure_description` TEXT,
  PRIMARY KEY (`document_structure_code`)
);

CREATE TABLE `Functional_Areas` (
  `functional_area_code` TEXT,
  `parent_functional_area_code` TEXT,
  `functional_area_description` TEXT,
  PRIMARY KEY (`functional_area_code`)
);

CREATE TABLE `Images` (
  `image_id` NUMBER,
  `image_alt_text` TEXT,
  `image_name` TEXT,
  `image_url` TEXT,
  PRIMARY KEY (`image_id`)
);

CREATE TABLE `Documents` (
  `document_code` TEXT,
  `document_structure_code` TEXT REFERENCES `Document_Structures`(`document_structure_code`),
  `document_type_code` TEXT,
  `access_count` NUMBER,
  `document_name` TEXT,
  PRIMARY KEY (`document_code`)
);

CREATE TABLE `Document_Functional_Areas` (
  `document_code` TEXT REFERENCES `Documents`(`document_code`),
  `functional_area_code` TEXT REFERENCES `Functional_Areas`(`functional_area_code`)
);

CREATE TABLE `Document_Sections` (
  `section_id` NUMBER,
  `document_code` TEXT REFERENCES `Documents`(`document_code`),
  `section_sequence` NUMBER,
  `section_code` TEXT,
  `section_title` TEXT,
  PRIMARY KEY (`section_id`)
);

CREATE TABLE `Document_Sections_Images` (
  `section_id` NUMBER REFERENCES `Document_Sections`(`section_id`),
  `image_id` NUMBER REFERENCES `Images`(`image_id`),
  PRIMARY KEY (`section_id`)
);

